using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 changed the default discriminator property from "Discriminator" to "$type".
        // Preserve the old property name for backward compatibility with existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminatorInJsonProperty("Discriminator");

        // EF Core 9 no longer prefixes the id with the discriminator ("Blog|1" -> "1").
        // Preserve the old id format for existing documents.
        modelBuilder.Entity<Blog>().HasIdProperty(b => b.Id, IdPropertyKind.DiscriminatorAndKey);

        // HasIndex is not supported by the Cosmos provider — removed.
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

